// Ground-truth probe: run the precompiled Python executable and capture exact bytes.
import { spawnSync } from 'node:child_process';

export const EXE = '/workspace/dataset/test2_executable';

export function py(a, b = 'x') {
  const r = spawnSync(EXE, ['--a', a, '--b', b], { encoding: 'buffer', maxBuffer: 1 << 28 });
  return {
    stdout: r.stdout ? r.stdout.toString('utf8') : '',
    stderr: r.stderr ? r.stderr.toString('utf8') : '',
    code: r.status,
  };
}

export function js(a, b = 'x', entry = '/output/test2.mjs') {
  const r = spawnSync(process.execPath, [entry, '--a', a, '--b', b], { encoding: 'buffer', maxBuffer: 1 << 28 });
  return {
    stdout: r.stdout ? r.stdout.toString('utf8') : '',
    stderr: r.stderr ? r.stderr.toString('utf8') : '',
    code: r.status,
  };
}
